INSERT INTO kb_documents (title, section, url, content, keywords, lang) VALUES
 ('Регламент ежегодных отпусков','Раздел 2. Расчёт отпуска','/kb/vacation#calc','Ежегодный оплачиваемый отпуск составляет 24 календарных дня в год. Отпуск рассчитывается пропорционально отработанному времени: за каждый полный месяц работы начисляется 2 дня. Заявка подаётся через платформу не позднее чем за 14 дней до начала отпуска и согласовывается непосредственным руководителем.','отпуск отпуска рассчитывается расчет дни дней остаток ежегодный отдых','ru'),
 ('Регламент ежегодных отпусков','Раздел 3. Порядок оформления','/kb/vacation#apply','Для оформления отпуска откройте раздел «Мои заявки», выберите «Заявка на отпуск», укажите даты. Платформа проверит остаток дней. После согласования руководителем заявка передаётся в Documentolog и проводится в 1С:ЗУП.','оформить оформление заявка отпуск подать согласование','ru'),
 ('Положение об авансе','Раздел 1. Условия выплаты','/kb/advance#terms','Аванс выплачивается 15 числа каждого месяца. Заявка на дополнительный аванс подаётся через платформу, сумма не может превышать 50% оклада. Решение принимает руководитель подразделения.','аванс выплата зарплата сумма дата аванса','ru'),
 ('Регламент больничных листов','Раздел 1. Действия работника','/kb/sick#steps','При болезни уведомите руководителя в первый день нетрудоспособности. Электронный листок нетрудоспособности передаётся в HR в течение 3 рабочих дней после закрытия.','больничный больничные болезнь заболел лист нетрудоспособности','ru'),
 ('Политика обучения Jana Academy','Раздел 1. Обязательное обучение','/kb/academy#mandatory','Назначенные курсы необходимо пройти в течение 30 дней. По завершении курса проводится тест, проходной балл 70%. Результаты сохраняются в профиле работника.','обучение курс курсы тест академия проходной балл назначенное','ru'),
 ('Командировки','Раздел 1. Оформление командировки','/kb/trip#apply','Командировка оформляется приказом за 5 рабочих дней до выезда. Суточные выплачиваются по утверждённым нормам компании.','командировка командировки суточные выезд','ru'),
 ('Жыл сайынғы демалыс регламенті','2-бөлім. Демалысты есептеу','/kb/vacation#calc','Жыл сайынғы ақылы демалыс жылына 24 күнтізбелік күнді құрайды. Әр толық жұмыс айы үшін 2 күн есептеледі. Өтінім демалыс басталуына 14 күн қалғанда платформа арқылы беріледі.','демалыс демалысты есептеу күн қалдық','kz');
